style.css:
/* Cute Duck + Hello Kitty Roblox Theme */

/* Pink + Yellow background */
body {
  background: linear-gradient(45deg, #ffb6c1, #fff176) !important;
}

/* Ducks everywhere */
body {
  background-image: url("https://upload.wikimedia.org/wikipedia/commons/3/32/Duck_icon.png") !important;
  background-size: 120px !important;
}

/* Hello Kitty corner decoration */
body::after {
  content: "";
  position: fixed;
  bottom: 20px;
  right: 20px;
  width: 120px;
  height: 120px;
  background-image: url("https://upload.wikimedia.org/wikipedia/en/0/05/Hello_Kitty_character_portrait.png");
  background-size: contain;
  background-repeat: no-repeat;
  pointer-events: none;
}

/* Cute buttons */
button {
  background: #ff69b4 !important;
  color: white !important;
  border-radius: 20px !important;
}

/* Pink links */
a {
  color: #ff1493 !important;
}
